package com.robothygenism.platform.device;
import com.fasterxml.jackson.core.JsonProcessingException;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.OffsetDateTime;import java.util.Map;import java.util.UUID;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.stereotype.Repository;
@Repository public class PostgresTelemetryStore implements TelemetryStore {private final JdbcClient jdbc;private final ObjectMapper json;public PostgresTelemetryStore(JdbcClient j,ObjectMapper o){jdbc=j;json=o;}public void append(UUID robotId,String messageId,long sequence,OffsetDateTime deviceTimestamp,OffsetDateTime receivedAt,Map<String,Object> payload){try{jdbc.sql("INSERT INTO \"TelemetrySample\" (\"robotId\",\"messageId\",sequence,payload,\"deviceTimestamp\",\"receivedAt\") VALUES (:robot,:message,:sequence,CAST(:payload AS jsonb),:device,:received) ON CONFLICT (\"robotId\",\"messageId\") DO NOTHING").param("robot",robotId).param("message",messageId).param("sequence",sequence).param("payload",json.writeValueAsString(payload)).param("device",deviceTimestamp).param("received",receivedAt).update();}catch(JsonProcessingException e){throw new IllegalArgumentException("Invalid telemetry payload",e);}}}
